"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"default\": () => (__WEBPACK_DEFAULT_EXPORT__)\n/* harmony export */ });\nconst BookReviewData = {\n    Reviews: [\n        {\n            volume: \"BOOK REVIEW\",\n            title: \"The Spy and the Traitor\",\n            slug: \"the-spy-and-the-traitor\",\n            author: \"Ben Macintyre\",\n            date: \"2018-09-20\",\n            excerpt: \"A taut, human story of betrayal and tradecraft following Oleg Gordievsky—the KGB colonel who became Britain’s most valuable asset.\",\n            archiveImage: \"/assets/images/space.jpg\",\n            banner: \"/assets/images/space.jpg\",\n            content: [\n                {\n                    text: \"<p><strong>Why it works:</strong> Macintyre balances meticulous sourcing with pacing that reads like a thriller. The book illuminates tradecraft without glamorizing it, and shows how personality—not just ideology—can flip loyalties.</p>\"\n                },\n                {\n                    text: \"<p><strong>Standout insight:</strong> The granular depiction of exfiltration planning highlights how contingency, luck, and interpersonal trust often trump gadgets in real operations.</p>\"\n                }\n            ],\n            images: [\n                \"/assets/images/space.jpg\"\n            ],\n            resources: {\n                References: [\n                    {\n                        label: \"Publisher\",\n                        url: \"https://www.penguinrandomhouse.com/\",\n                        external: true\n                    },\n                    {\n                        label: \"Wikipedia\",\n                        url: \"https://en.wikipedia.org/wiki/The_Spy_and_the_Traitor\",\n                        external: true\n                    }\n                ]\n            }\n        },\n        {\n            volume: \"BOOK REVIEW\",\n            title: \"The Billion Dollar Spy\",\n            slug: \"the-billion-dollar-spy\",\n            author: \"David E. Hoffman\",\n            date: \"2015-07-07\",\n            excerpt: \"The true story of Adolf Tolkachev, an engineer who handed the CIA a treasure trove of Soviet avionics secrets in Moscow.\",\n            archiveImage: \"/assets/images/space.jpg\",\n            banner: \"/assets/images/space.jpg\",\n            content: [\n                {\n                    text: \"<p><strong>Read for:</strong> Operational friction—dead drops, surveillance detection routes, and the bureaucratic pressures that shape risk decisions.</p>\"\n                },\n                {\n                    text: \"<p><strong>My take:</strong> Hoffman captures the lonely psychology of human intelligence collection, where routine and paranoia battle on every page.</p>\"\n                }\n            ],\n            images: [\n                \"/assets/images/space.jpg\"\n            ],\n            resources: {\n                References: [\n                    {\n                        label: \"Publisher\",\n                        url: \"https://www.penguinrandomhouse.com/\",\n                        external: true\n                    },\n                    {\n                        label: \"Wikipedia\",\n                        url: \"https://en.wikipedia.org/wiki/The_Billion_Dollar_Spy\",\n                        external: true\n                    }\n                ]\n            }\n        },\n        {\n            volume: \"BOOK REVIEW\",\n            title: \"Legacy of Ashes: The History of the CIA\",\n            slug: \"legacy-of-ashes\",\n            author: \"Tim Weiner\",\n            date: \"2007-08-07\",\n            excerpt: \"An award-winning, document-heavy critique of the CIA’s successes and failures from the Cold War onward.\",\n            archiveImage: \"/assets/images/space.jpg\",\n            banner: \"/assets/images/space.jpg\",\n            content: [\n                {\n                    text: \"<p><strong>Strength:</strong> Primary-source rigor. Weiner leans on declassified records to cut through myth-making.</p>\"\n                },\n                {\n                    text: \"<p><strong>Caveat:</strong> The narrative skews critical; useful as a counterweight to celebratory histories but best paired with alternative perspectives.</p>\"\n                }\n            ],\n            images: [\n                \"/assets/images/space.jpg\"\n            ],\n            resources: {\n                References: [\n                    {\n                        label: \"Publisher\",\n                        url: \"https://www.penguinrandomhouse.com/\",\n                        external: true\n                    },\n                    {\n                        label: \"Wikipedia\",\n                        url: \"https://en.wikipedia.org/wiki/Legacy_of_Ashes\",\n                        external: true\n                    }\n                ]\n            }\n        },\n        {\n            volume: \"BOOK REVIEW\",\n            title: \"Sandworm: A New Era of Cyberwar\",\n            slug: \"sandworm\",\n            author: \"Andy Greenberg\",\n            date: \"2019-11-05\",\n            excerpt: \"A gripping account of the Russian hacking group behind some of the most disruptive cyberattacks, and what their campaigns signal for global security.\",\n            archiveImage: \"/assets/images/space.jpg\",\n            banner: \"/assets/images/space.jpg\",\n            content: [\n                {\n                    text: \"<p><strong>Why it matters:</strong> Shows how state-aligned actors test thresholds with ‘plausible deniability’ while inflicting real-world damage.</p>\"\n                },\n                {\n                    text: \"<p><strong>Takeaway:</strong> Cyber risk is systemic—supply chains, ICS, and default configurations can propagate blast radius far beyond the target.</p>\"\n                }\n            ],\n            images: [\n                \"/assets/images/space.jpg\"\n            ],\n            resources: {\n                References: [\n                    {\n                        label: \"Publisher\",\n                        url: \"https://www.penguinrandomhouse.com/\",\n                        external: true\n                    },\n                    {\n                        label: \"Wikipedia\",\n                        url: \"https://en.wikipedia.org/wiki/Sandworm_(book)\",\n                        external: true\n                    }\n                ]\n            }\n        },\n        {\n            volume: \"BOOK REVIEW\",\n            title: \"This Is How They Tell Me the World Ends\",\n            slug: \"this-is-how-they-tell-me-the-world-ends\",\n            author: \"Nicole Perlroth\",\n            date: \"2021-02-09\",\n            excerpt: \"A deep dive into the zero-day market and the geopolitics of cyberweapons—where incentives, secrecy, and demand collide.\",\n            archiveImage: \"/assets/images/space.jpg\",\n            banner: \"/assets/images/space.jpg\",\n            content: [\n                {\n                    text: \"<p><strong>Best parts:</strong> Ground-level reporting on brokers and buyers, and the policy vacuum that allowed the market to scale.</p>\"\n                },\n                {\n                    text: \"<p><strong>Bottom line:</strong> Patch velocity, transparency, and norms are lagging the economics of exploitation.</p>\"\n                }\n            ],\n            images: [\n                \"/assets/images/space.jpg\"\n            ],\n            resources: {\n                References: [\n                    {\n                        label: \"Publisher\",\n                        url: \"https://www.bloomsbury.com/\",\n                        external: true\n                    },\n                    {\n                        label: \"Wikipedia\",\n                        url: \"https://en.wikipedia.org/wiki/This_Is_How_They_Tell_Me_the_World_Ends\",\n                        external: true\n                    }\n                ]\n            }\n        }\n    ]\n};\n/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (BookReviewData);\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(pages-dir-node)/./src/data/BookReviewData.js\n");

